/* ---- relocatability: the wire is a pure length-prefixed stream AND the
   decoded storage is pointer-free — every closure type is a plain C struct
   of scalars and arrays, so instances can be memcpy'd, mmap'd, shared
   across processes, and walked through descriptor offsets. C has no way to
   put a pointer, a vtable or a non-trivial member in one of these, which is
   why the property is a fact of the language here rather than an assert.
   What IS asserted is the layout the build version was taken over. */

/* ---- the cook's layout contract (docs/SPEC-TABLES.md §20.3) ----

   The compiler derived every number below from the declaration and folded it
   into the BUILD VERSION; these asserts are this compiler saying whether it
   agrees. The model is not self-evidently right — on 32-bit System V
   alignof(uint64_t) is 4, not 8 — which is precisely why it is asserted
   rather than assumed. */
SCHEMA_TABLE_STATIC_ASSERT( PaddedRow_sizeof, sizeof( PaddedRow ) == 64, "PaddedRow's sizeof moved: the build version was taken over 64, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
SCHEMA_TABLE_STATIC_ASSERT( PaddedRow_alignof, SCHEMA_TABLE_ALIGNOF( PaddedRow ) == 8, "PaddedRow's alignof moved: the build version was taken over 8 (docs/SPEC-TABLES.md §20.3)" );
SCHEMA_TABLE_STATIC_ASSERT( PaddedRow_tag_offset, offsetof( PaddedRow, tag ) == 0, "PaddedRow's field tag moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
SCHEMA_TABLE_STATIC_ASSERT( PaddedRow_value_offset, offsetof( PaddedRow, value ) == 8, "PaddedRow's field value moved: the build version was taken over offset 8 (docs/SPEC-TABLES.md §20.3)" );
SCHEMA_TABLE_STATIC_ASSERT( PaddedRow_flag_offset, offsetof( PaddedRow, flag ) == 16, "PaddedRow's field flag moved: the build version was taken over offset 16 (docs/SPEC-TABLES.md §20.3)" );
SCHEMA_TABLE_STATIC_ASSERT( PaddedRow_id_offset, offsetof( PaddedRow, id ) == 20, "PaddedRow's field id moved: the build version was taken over offset 20 (docs/SPEC-TABLES.md §20.3)" );
SCHEMA_TABLE_STATIC_ASSERT( PaddedRow_label_offset, offsetof( PaddedRow, label ) == 24, "PaddedRow's field label moved: the build version was taken over offset 24 (docs/SPEC-TABLES.md §20.3)" );
SCHEMA_TABLE_STATIC_ASSERT( PaddedRow_slots_offset, offsetof( PaddedRow, slots ) == 44, "PaddedRow's field slots moved: the build version was taken over offset 44 (docs/SPEC-TABLES.md §20.3)" );
SCHEMA_TABLE_STATIC_ASSERT( PaddedRow_teams_offset, offsetof( PaddedRow, teams ) == 52, "PaddedRow's field teams moved: the build version was taken over offset 52 (docs/SPEC-TABLES.md §20.3)" );
SCHEMA_TABLE_STATIC_ASSERT( PaddedRow_counter_offset, offsetof( PaddedRow, counter ) == 56, "PaddedRow's field counter moved: the build version was taken over offset 56 (docs/SPEC-TABLES.md §20.3)" );
SCHEMA_TABLE_STATIC_ASSERT( PaddedFrame_sizeof, sizeof( PaddedFrame ) == 4136, "PaddedFrame's sizeof moved: the build version was taken over 4136, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
SCHEMA_TABLE_STATIC_ASSERT( PaddedFrame_alignof, SCHEMA_TABLE_ALIGNOF( PaddedFrame ) == 8, "PaddedFrame's alignof moved: the build version was taken over 8 (docs/SPEC-TABLES.md §20.3)" );
SCHEMA_TABLE_STATIC_ASSERT( PaddedFrame_marker_offset, offsetof( PaddedFrame, marker ) == 0, "PaddedFrame's field marker moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
SCHEMA_TABLE_STATIC_ASSERT( PaddedFrame_stamp_offset, offsetof( PaddedFrame, stamp ) == 8, "PaddedFrame's field stamp moved: the build version was taken over offset 8 (docs/SPEC-TABLES.md §20.3)" );
